                # enclosed hole? flood fill 0-cells of bbox from border within pattern
                ph,pw=len(pat),len(pat[0])
                outseen=set(); stq=[(y,x) for y in range(ph) for x in range(pw) if pat[y][x]==0 and (y in(0,ph-1) or x in(0,pw-1))]
