    shapes.sort(key=lambda s:(s['r0'],s['c0']))
    out=[[0]*w for _ in range(h)]
    for s in shapes:
        ph=len(s['pat']); pw=len(s['pat'][0])
        if s['up']:
            r=0
            while True:
                ok=all(0<=r+y<h and out[r+y][s['c0']+x]==0 for y in range(ph) for x in range(pw) if s['pat'][y][x])
                if ok: break
                r+=1
        else:
            r=h-ph
            while True:
                ok=all(0<=r+y<h and out[r+y][s['c0']+x]==0 for y in range(ph) for x in range(pw) if s['pat'][y][x])
                if ok: break
                r-=1
        for y in range(ph):
            for x in range(pw):
                if s['pat'][y][x]: out[r+y][s['c0']+x]=s['col']
    return out
